// Tunable parameters for the KESTREL flight core.
// Defaults were tuned in the 6-DOF simulator (sim/) and verified by Monte-Carlo runs.
#pragma once
#include <cstdint>

namespace kestrel {

constexpr int kMotorPoints = 24;

// Nominal behaviour of one motor in THIS airframe, generated by firmware/tools/gen_motor_db.py
// from sim/kestrel/motors.json + design.json. Used to schedule the TVC gain with thrust.
struct MotorProfile {
    const char* name;
    uint8_t n;
    float t[kMotorPoints];        // s since ignition
    float thrust[kMotorPoints];   // N
    float i_lat[kMotorPoints];    // vehicle pitch/yaw inertia about the CG, kg m^2
    float lever[kMotorPoints];    // CG -> gimbal pivot distance, m
    float imu_arm[kMotorPoints];  // IMU position ahead of the CG along body x, m (for lever-arm correction)
    float burn_time;              // s
    float detect_offset;          // s from ignition until launch detection normally triggers
    float apogee_time_nominal;    // s after ignition (simulated, no wind)
};

struct TvcGains {
    float kp{110.0f};             // rad/s^2 per rad of attitude error
    float ki{25.0f};              // rad/s^2 per rad*s
    float kd{16.0f};              // rad/s^2 per rad/s of body rate
    float integ_limit{0.12f};     // rad*s
    float max_gimbal_deg{6.0f};
    float thrust_floor_n{5.0f};   // never divide by less thrust than this
    float roll_lead_s{0.030f};    // actuator latency compensated against roll rate
    float rate_lpf_hz{35.0f};
    float soft_start_s{0.20f};    // gain ramp while on the launch rod
};

struct FlightLogicConfig {
    float launch_accel_g{2.0f};          // body-axis specific force for launch detect
    float launch_hold_s{0.030f};
    float burnout_accel_g{0.25f};        // specific force below this after min burn => coast
    float min_burn_s{0.4f};
    float apogee_min_alt_m{15.0f};
    int apogee_confirm_samples{3};       // consecutive baro updates with vz < 0
    float deploy_lockout_after_burnout_s{0.6f};
    float deploy_backup_margin_s{3.0f};  // deploy anyway at nominal apogee time + this
    float descent_rate_deploy_mps{12.0f};// emergency: falling faster than this in COAST => deploy
    float abort_tilt_deg{50.0f};         // tilt from target during boost that flags an abort
    float abort_rate_dps{250.0f};        // lateral body rate that flags a tumble (abort)
    float abort_rate_hold_s{0.10f};
    float abort_deploy_speed_mps{30.0f}; // in abort: deploy once inertial speed drops below this
    float landed_still_s{5.0f};
    float landed_alt_band_m{2.0f};
    bool hold_launch_attitude{true};     // true: hold the rod direction, false: hold vertical
    float calib_still_s{3.0f};           // stationary time needed before READY
    float min_vbat_v{6.6f};              // 2S pack: refuse READY below this
};

struct KfConfig {
    float accel_sigma{0.6f};      // m/s^2 process noise on the accelerometer input
    float baro_sigma{0.35f};      // m, baro altitude noise (coast/descent)
    float baro_sigma_boost{2.5f}; // m, baro is distrusted while the motor burns
};

struct Config {
    TvcGains tvc;
    FlightLogicConfig logic;
    KfConfig kf;
    const MotorProfile* motor{nullptr};
};

}  // namespace kestrel
